// Minimal stub of the VS Code API surface this extension touches.
//
// Everything the real API DOES is recorded, not swallowed. Three round-2 findings
// traced to this file rather than to a test: `show()`/`hide()` were indistinguishable
// no-ops (so a permanently hidden status button passed), the show ORDER was not kept
// (so dropping the "land back on the first group" call passed), and the
// `onDidCloseTerminal` callback was discarded (so wiping the whole pane registry when
// one pane closed passed). A stub that cannot express a behaviour cannot test it.
const state = {
  terminals: [], disposed: [], errors: [], warnings: [], status: null,
  commands: {}, config: {}, answer: undefined, modals: [],
  quickPick: null, quickPickCalls: [],
  shown: [],            // terminals in the order show() was called, i.e. what you end on
  closeHandlers: [],    // registered onDidCloseTerminal callbacks
}
class ThemeIcon { constructor(id){ this.id = id } }
class MarkdownString { constructor(v){ this.value = v } }
const StatusBarAlignment = { Left: 1, Right: 2 }
function createTerminal(opts) {
  // SNAPSHOT the options AT THE CALL. Keeping the caller's object by reference let a
  // production path create every child with `location` absent and put it back
  // afterwards: VS Code reads the object at the call and made eight TABS, while every
  // parentage assertion here read the restored value and passed. A stub that reports
  // a LATER state is not reporting the API call.
  //   MUTANT: `createTerminal(parent ? (delete opts.location, opts) : opts)` followed
  //   by `if (parent) opts.location = { parentTerminal: parent }`.
  // The location object is copied too -- `parentTerminal` keeps its IDENTITY, which
  // is what `leaders()`/`groupSizes()` compare against.
  const snap = Object.assign({}, opts)
  if (opts && opts.location) snap.location = Object.assign({}, opts.location)
  const t = {
    opts: snap, shown: 0,
    dispose(){ state.disposed.push(t) },
    show(){ t.shown++; state.shown.push(t) },
  }
  state.terminals.push(t); return t
}
// Emit a real close event, the way VS Code does when the user closes one pane.
state.closeTerminal = (t) => { for (const h of state.closeHandlers) h(t) }
// Which terminal is you looking at? The last one shown that has not been disposed.
state.activeTerminal = () => {
  for (let i = state.shown.length - 1; i >= 0; i--) {
    if (!state.disposed.includes(state.shown[i])) return state.shown[i]
  }
  return null
}
module.exports = {
  __state: state, ThemeIcon, MarkdownString, StatusBarAlignment,
  window: {
    createTerminal,
    createStatusBarItem: () => (state.status = {
      text: '', tooltip: null, command: null, visible: false,
      show(){ this.visible = true }, hide(){ this.visible = false }, dispose(){},
    }),
    showErrorMessage: (m) => state.errors.push(m),
    showWarningMessage: (m, opts, ...items) => {
      state.warnings.push(m)
      if (opts && opts.modal) {
        state.modals.push({ message: m, items })
        // `answer` may be a function of the buttons that were ACTUALLY offered, so a
        // test can click "the limiting one" without hard-coding its wording -- which
        // is what let a reworded button silently fall through to "open everything".
        return Promise.resolve(typeof state.answer === 'function' ? state.answer(items) : state.answer)
      }
      return Promise.resolve(undefined)
    },
    // `quickPick` is a function of the offered items, so a test can assert what the
    // picker OFFERED (notably: whether every row arrives pre-ticked) as well as choose.
    showQuickPick: async (items, opts) => {
      const resolved = await items
      // SNAPSHOT at the call, for the same reason createTerminal does: the recorded fact
      // has to be what the picker was OFFERED, not what the offer was edited into
      // afterwards. `picked: true` restored after the await would otherwise read back as
      // pre-ticked while VS Code had drawn every row unticked. This is the createTerminal
      // finding's own shape at the second stub entry point that keeps a caller-owned
      // object -- fixed as a class, not as the one site the lens named.
      //   MUTANT: build the items with `picked: false`, then flip them true after the
      //   await (5-expression mutant R6-T01b).
      // Each item is copied one level deep: `row` keeps its IDENTITY, which is what the
      // pane/roster association assertions compare, and `state.quickPick` is still handed
      // the ORIGINAL objects, because VS Code returns the caller's own items.
      const snapItems = Array.isArray(resolved)
        ? resolved.map((o) => (o && typeof o === 'object' ? Object.assign({}, o) : o))
        : resolved
      state.quickPickCalls.push({ items: snapItems, opts: opts && Object.assign({}, opts) })
      return typeof state.quickPick === 'function' ? state.quickPick(resolved) : state.quickPick
    },
    onDidCloseTerminal: (fn) => {
      state.closeHandlers.push(fn)
      return { dispose(){ state.closeHandlers = state.closeHandlers.filter((x) => x !== fn) } }
    },
  },
  commands: { registerCommand: (id, fn) => { state.commands[id] = fn; return { dispose(){} } } },
  workspace: { getConfiguration: () => ({ get: (k) => state.config[k] }) },
}
